SELECT 
    FLOW_DIRECTION as direction,
    ROUND(AVG(FLOW_COUNT), 2) as count
FROM CLOUDWALK.FLOW_ANALYSIS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
GROUP BY FLOW_DIRECTION

SELECT TO_CHAR(RECORD_TIME, 'HH24') as hour, ROUND(AVG(FLOW_COUNT), 2) as count FROM CLOUDWALK.FLOW_ANALYSIS WHERE 1=1
AND DEVICE_CODE = #{deviceCode}
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime} GROUP BY TO_CHAR(RECORD_TIME, 'HH24') ORDER BY hour

SELECT 
FROM CLOUDWALK.FLOW_ANALYSIS
WHERE RECORD_TIME BETWEEN #{startTime} AND #{endTime}

    AND TOURISM_NAME = #{tourismName}

ORDER BY RECORD_TIME DESC

SELECT 
FROM CLOUDWALK.FLOW_ANALYSIS
WHERE DEVICE_CODE = #{deviceCode}
AND RECORD_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY RECORD_TIME DESC

SELECT 
FROM CLOUDWALK.FLOW_ANALYSIS


        AND DEVICE_CODE = #{params.deviceCode}


