SELECT
    TO_CHAR(RECORD_TIME, 'HH24') AS hour,
    SUM(FLOW_COUNT) AS count
FROM FLOW_ANALYSIS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY TO_CHAR(RECORD_TIME, 'HH24')
ORDER BY hour

SELECT
    FLOW_DIRECTION AS direction,
    SUM(FLOW_COUNT) AS count
FROM FLOW_ANALYSIS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY FLOW_DIRECTION

SELECT
    TO_CHAR(RECORD_TIME, 'YYYY-MM-DD HH24:MI:SS') AS time,
    SUM(FLOW_COUNT) AS count
FROM FLOW_ANALYSIS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY RECORD_TIME
ORDER BY RECORD_TIME

